"""Multi-backend agent session -> ATIF adapters.

Each backend's raw session log (jsonl) is converted into an ATIF dict -- the
same interchange format aqa's own ReAct trajectories use
(:mod:`aqa.agent_eval.atif`), so downstream dataset builders
(:mod:`aqa.agent.traces_export`) work uniformly across agent backends.

One adapter per backend, modeled on Harbor's per-backend ``_convert_*_to_atif``
converters (harbor-framework/harbor, ``src/harbor/agents/installed/*.py``);
the format contract for each backend is documented in
``docs/trajectory_data_plan.md``.  Adapters are deliberately lossy where the
source is (e.g. openclaw logs carry no model name; pass it via ``model_name``).
"""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any, Protocol

from ..logging_util import get_logger

_log = get_logger("agent.adapters")

SCHEMA_VERSION = "ATIF-v1.7"


class Adapter(Protocol):
    """A backend adapter: detect a raw session artifact and convert it to ATIF."""

    name: str

    def detect(self, path: Path) -> bool:
        """True when ``path`` looks like this backend's session artifact."""
        ...

    def to_atif(self, path: Path, *, model_name: str = "",
                instruction: str | None = None) -> dict[str, Any] | None:
        """Convert the session at ``path`` to an ATIF dict (None = unusable)."""
        ...


# ── shared builders ──────────────────────────────────────────────────────────
def iter_jsonl(path: Path) -> list[dict[str, Any]]:
    """Parse a jsonl file tolerantly (skip blank/malformed lines)."""
    events: list[dict[str, Any]] = []
    for line in Path(path).read_text(errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            _log.debug("%s: skipping non-JSON line", path.name)
            continue
        if isinstance(obj, dict):
            events.append(obj)
    return events


def flatten_content(content: Any) -> str:
    """Normalize content (str | parts list | None) to text."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "".join(
            part.get("text", "") for part in content
            if isinstance(part, dict) and part.get("type") in ("text", "input_text", "output_text")
        )
    return ""


def parse_arguments(raw: Any) -> dict[str, Any]:
    """Tool-call arguments may be a dict or a JSON string (or neither)."""
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str):
        try:
            parsed = json.loads(raw)
            return parsed if isinstance(parsed, dict) else {"input": parsed}
        except json.JSONDecodeError:
            return {"input": raw}
    return {"input": raw} if raw is not None else {}


def make_trajectory(*, session_id: str, agent_name: str, steps: list[dict[str, Any]],
                    model_name: str = "", agent_version: str = "",
                    final_metrics: dict[str, Any] | None = None,
                    extra: dict[str, Any] | None = None) -> dict[str, Any]:
    """Assemble the ATIF root dict (steps renumbered 1..N)."""
    for i, step in enumerate(steps, start=1):
        step["step_id"] = i
    traj: dict[str, Any] = {
        "schema_version": SCHEMA_VERSION,
        "session_id": session_id,
        "agent": {
            "name": agent_name,
            "version": agent_version or "unknown",
            **({"model_name": model_name} if model_name else {}),
        },
        "steps": steps,
    }
    if final_metrics:
        traj["final_metrics"] = final_metrics
    if extra:
        traj["extra"] = extra
    return traj


class StepBuilder:
    """Accumulates ATIF steps with tool_call/observation correlation.

    ``add_agent`` starts an agent step carrying text + tool_calls;
    ``add_tool_result`` appends an ObservationResult onto the step that issued
    the call (unmatched results become standalone agent steps, mirroring
    Harbor's orphan handling).
    """

    def __init__(self) -> None:
        self.steps: list[dict[str, Any]] = []
        self._pending: dict[str, dict[str, Any]] = {}  # call_id -> step

    def add_user(self, text: str, **kw: Any) -> dict[str, Any]:
        step = {"source": "user", "message": text, **kw}
        self.steps.append(step)
        return step

    def add_system(self, text: str, **kw: Any) -> dict[str, Any]:
        step = {"source": "system", "message": text, **kw}
        self.steps.append(step)
        return step

    def add_agent(self, text: str, tool_calls: list[dict[str, Any]] | None = None,
                  **kw: Any) -> dict[str, Any]:
        step: dict[str, Any] = {"source": "agent", "message": text,
                                "llm_call_count": 1, **kw}
        if tool_calls:
            step["tool_calls"] = tool_calls
            step["observation"] = {"results": []}
            for tc in tool_calls:
                self._pending[tc["tool_call_id"]] = step
        self.steps.append(step)
        return step

    def add_tool_result(self, call_id: str, content: str,
                        extra: dict[str, Any] | None = None) -> bool:
        """Attach a tool result to its issuing step; False when orphaned."""
        step = self._pending.pop(call_id, None)
        if step is None:
            return False
        result: dict[str, Any] = {"source_call_id": call_id, "content": content}
        if extra:
            result["extra"] = extra
        step.setdefault("observation", {"results": []})["results"].append(result)
        return True


def first_existing(*candidates: Path) -> Path | None:
    for c in candidates:
        if Path(c).exists():
            return Path(c)
    return None


def env_or(default: str, *names: str) -> str:
    for name in names:
        val = os.environ.get(name)
        if val:
            return val
    return default

"""OpenClaw session adapter: openclaw.session.jsonl -> ATIF.

Source format (harbor openclaw.py contract): jsonl of
``{"type":"message","timestamp":...,"message":{role, content, ...}}`` rows.
Roles consumed: ``user`` / ``assistant`` / ``toolResult``.  Assistant content
is a parts array (``text`` / ``toolCall{id,name,arguments}``); toolResult rows
carry ``toolCallId`` + ``details.aggregated`` (fallback: text parts).  Usage
lives per assistant row (``usage.{input,output,cacheRead,cacheWrite}``).

OpenClaw logs carry no model name -- pass ``model_name`` (``provider/model``)
explicitly.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from .base import (SCHEMA_VERSION, StepBuilder, env_or, flatten_content,
                   iter_jsonl, make_trajectory, parse_arguments)


class OpenclawAdapter:
    name = "openclaw"

    def detect(self, path: Path) -> bool:
        return path.name.endswith(".jsonl") and ("openclaw" in path.name or "session" in path.name)

    def to_atif(self, path: Path, *, model_name: str = "",
                instruction: str | None = None) -> dict[str, Any] | None:
        events = iter_jsonl(path)
        sb = StepBuilder()
        first_user = True
        total_input = total_output = total_cache_read = total_cache_write = 0
        for ev in events:
            if ev.get("type") != "message":
                continue
            msg = ev.get("message") or {}
            role = msg.get("role")
            ts = ev.get("timestamp") if isinstance(ev.get("timestamp"), str) else None
            if role == "user":
                text = flatten_content(msg.get("content"))
                if first_user and instruction:
                    text = instruction
                first_user = False
                sb.add_user(text, **({"timestamp": ts} if ts else {}))
            elif role == "assistant":
                parts = msg.get("content") or []
                text = "".join(p.get("text", "") for p in parts
                               if isinstance(p, dict) and p.get("type") == "text")
                if not text:
                    text = msg.get("errorMessage") or "(no assistant text)"
                calls = [
                    {"tool_call_id": p.get("id", ""), "function_name": p.get("name", ""),
                     "arguments": parse_arguments(p.get("arguments"))}
                    for p in parts if isinstance(p, dict) and p.get("type") == "toolCall"
                ]
                usage = msg.get("usage") or {}
                metrics = None
                if usage:
                    total_input += usage.get("input", 0) + usage.get("cacheRead", 0)
                    total_output += usage.get("output", 0)
                    total_cache_read += usage.get("cacheRead", 0)
                    total_cache_write += usage.get("cacheWrite", 0)
                    metrics = {
                        "prompt_tokens": usage.get("input", 0) + usage.get("cacheRead", 0),
                        "completion_tokens": usage.get("output", 0),
                        "cached_tokens": usage.get("cacheRead", 0),
                        "extra": {"cache_write_tokens": usage.get("cacheWrite", 0)},
                    }
                kw: dict[str, Any] = {"metrics": metrics} if metrics else {}
                if model_name:
                    kw["model_name"] = model_name
                if ts:
                    kw["timestamp"] = ts
                sb.add_agent(text, calls or None, **kw)
            elif role == "toolResult":
                call_id = msg.get("toolCallId", "")
                content = (msg.get("details") or {}).get("aggregated") \
                    or flatten_content(msg.get("content"))
                sb.add_tool_result(call_id, content)

        if len(sb.steps) < 2:
            return None
        final = None
        if total_input or total_output:
            final = {"total_prompt_tokens": total_input,
                     "total_completion_tokens": total_output,
                     "total_cached_tokens": total_cache_read,
                     "extra": {"cache_write_tokens": total_cache_write}}
        return make_trajectory(
            session_id=path.stem.replace(".session", ""),
            agent_name="openclaw",
            model_name=model_name or env_or("", "OPENCLAW_MODEL"),
            steps=sb.steps, final_metrics=final,
        )


ADAPTER = OpenclawAdapter()

"""Copilot CLI session adapter: copilot-cli.jsonl -> ATIF.

Source format (harbor copilot_cli.py contract): jsonl of copilot
``--output-format=json`` events, two coexisting schemas:

* flat (Anthropic models): ``type`` in message / tool_use / tool_result /
  usage, with role/content/id/name/input/tool_use_id;
* session-event (OpenAI models): namespaced ``type`` (``user.message`` /
  ``assistant.message`` / ``tool.execution_complete`` / ``result``) with the
  payload under ``data``.

Session id is not carried in the log -- Harbor hardcodes "copilot-cli".
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from .base import (StepBuilder, env_or, flatten_content, iter_jsonl,
                   make_trajectory, parse_arguments)

_RESULT_KEYS = ("content", "output", "stdout", "text", "message")


def _result_text(data: dict[str, Any]) -> str:
    result = data.get("result")
    if isinstance(result, dict):
        for key in _RESULT_KEYS:
            if result.get(key):
                return str(result[key])
        return json_dumps(result)
    if result is not None:
        return str(result)
    if data.get("error"):
        return str(data["error"])
    return ""


def json_dumps(obj: Any) -> str:
    import json

    return json.dumps(obj, ensure_ascii=False)


class CopilotAdapter:
    name = "copilot"

    def detect(self, path: Path) -> bool:
        return "copilot" in path.name and path.suffix == ".jsonl"

    def to_atif(self, path: Path, *, model_name: str = "",
                instruction: str | None = None) -> dict[str, Any] | None:
        events = iter_jsonl(path)
        sb = StepBuilder()
        total_in = total_out = 0
        model_seen = model_name
        first_user = True
        for ev in events:
            etype = ev.get("type", "")
            ts = ev.get("timestamp") if isinstance(ev.get("timestamp"), str) else None
            tsk = {"timestamp": ts} if ts else {}

            if etype == "message":  # flat schema
                role = ev.get("role", "user")
                text = flatten_content(ev.get("content"))
                if role == "assistant":
                    kw: dict[str, Any] = dict(tsk)
                    if ev.get("model"):
                        kw["model_name"] = ev["model"]
                        model_seen = model_seen or ev["model"]
                    sb.add_agent(text, **kw)
                else:
                    if first_user and instruction:
                        text = instruction
                    first_user = False
                    sb.add_user(text, **tsk)
            elif etype == "tool_use":
                name = ev.get("name", "")
                call_id = ev.get("id", "")
                sb.add_agent(f"Executed {name}", [{
                    "tool_call_id": call_id, "function_name": name,
                    "arguments": parse_arguments(ev.get("input")),
                }], **tsk)
            elif etype == "tool_result":
                sb.add_tool_result(ev.get("tool_use_id", ""),
                                   flatten_content(ev.get("content")) or json_dumps(ev.get("content")),
                                   extra={k: v for k, v in ev.items()
                                          if k not in ("type", "tool_use_id", "content", "timestamp")})
            elif etype == "usage":
                total_in += ev.get("input_tokens", 0)
                total_out += ev.get("output_tokens", 0)

            elif etype == "user.message":  # session-event schema
                data = ev.get("data") or {}
                text = data.get("content", "")
                if first_user and instruction:
                    text = instruction
                first_user = False
                sb.add_user(text, **tsk)
            elif etype == "assistant.message":
                data = ev.get("data") or {}
                text = data.get("content", "")
                calls = [
                    {"tool_call_id": tc.get("toolCallId", ""),
                     "function_name": tc.get("name", ""),
                     "arguments": parse_arguments(tc.get("arguments"))}
                    for tc in data.get("toolRequests") or []
                ]
                kw = dict(tsk)
                if data.get("model"):
                    kw["model_name"] = data["model"]
                    model_seen = model_seen or data["model"]
                if data.get("outputTokens"):
                    total_out += data["outputTokens"]
                    kw["metrics"] = {"completion_tokens": data["outputTokens"]}
                if text or calls:
                    sb.add_agent(text, calls or None, **kw)
            elif etype == "tool.execution_complete":
                data = ev.get("data") or {}
                sb.add_tool_result(data.get("toolCallId", ""), _result_text(data),
                                   extra={k: v for k, v in data.items()
                                          if k not in ("toolCallId", "result")})
            # result / tool.execution_* / assistant.turn_* / session.* ignored

        if len(sb.steps) < 2:
            return None
        final = None
        if total_in or total_out:
            final = {"total_prompt_tokens": total_in or None,
                     "total_completion_tokens": total_out or None}
            final = {k: v for k, v in final.items() if v is not None}
        return make_trajectory(
            session_id="copilot-cli",  # logs carry no session id
            agent_name="copilot",
            model_name=model_seen or env_or("", "COPILOT_MODEL"),
            steps=sb.steps, final_metrics=final or None,
        )


